const { ApiGatewayManagementApiClient, PostToConnectionCommand } = require('@aws-sdk/client-apigatewaymanagementapi');
const { db } = require('../db');

exports.handler = async (event) => {
  const connectionId = event.requestContext.connectionId;
  const userOrgId = event.requestContext.authorizer?.orgId;
  const body = JSON.parse(event.body || '{}');
  const targetChannelId = body.channelId;

  const channel = await db.query(
    'SELECT id FROM chat_channels WHERE id = $1 AND org_id = $2',
    [targetChannelId, userOrgId]
  );
  if (!channel.rows.length) {
    return { statusCode: 403, body: 'Forbidden: unauthorized channel subscription' };
  }

  await db.query(
    'INSERT INTO websocket_subscriptions (connection_id, channel_id) VALUES ($1, $2)',
    [connectionId, targetChannelId]
  );

  return { statusCode: 200, body: 'Subscribed' };
};
